def o(n): return " Sólo puedes usar este efecto de \"%s\" una vez por turno." % n
def e(n): return " Sólo puedes usar cada efecto de \"%s\" una vez por turno." % n
def a(n): return " Sólo puedes activar 1 \"%s\" por turno." % n
def u(n): return " Sólo puedes usar 1 efecto de \"%s\" por turno, y sólo una vez ese turno." % n
def each2(n): return " Sólo puedes usar cada uno de los siguientes efectos de \"%s\" una vez por turno." % n
L4 = "2 monstruos de Nivel 4\n"
L8 = "2 monstruos de Nivel 8\n"
NOEXX = "no puedes Invocar monstruos de Modo Especial desde el Deck Extra por el resto de este turno, excepto Monstruos Xyz"
W35 = "Si esta carta es usada para la Invocación Xyz de un monstruo de AGUA, puede ser tratada como un monstruo de Nivel 3 o 5."
N34 = "Si esta carta es usada para la Invocación Xyz de un monstruo \"Number\", puede ser tratada como un monstruo de Nivel 3 o 4. "
PG = "\"Photon\" o \"Galaxy\""
GEPD = "\"Galaxy-Eyes Photon Dragon\""
NN = "\"Numeron Network\""
GATE = "3 monstruos de Nivel 1\nNo puede ser destruido en batalla. Al final del Damage Step, si esta carta batalló con un monstruo del adversario: puedes desacoplar 1 material de esta carta; duplica el ATK de todos los monstruos \"Numeron\" que controles en este momento, hasta el final de este turno."
TR = "(Transfiere sus materiales a esta carta.) "
ES = {
"Gagagaga Magician": L4 + "Puedes desacoplar 1 material de esta carta y después seleccionar 1 Monstruo Xyz en tu Cementerio, excepto \"Gagagaga Magician\"; Invócalo de Modo Especial, pero niega sus efectos." + o("Gagagaga Magician") + " Un Monstruo Xyz \"Utopic Future\" que tenga esta carta como material gana este efecto.\n● Durante tu Main Phase: puedes desacoplar 2 materiales de esta carta y después seleccionar 1 Monstruo Xyz que controles; hasta el final de este turno, cambia su ATK a 4000, y además niega sus efectos.",
"Gagagaga Girl": L4 + "Si esta carta tiene como material una carta \"Zubaba\", \"Gagaga\", \"Gogogo\" o \"Dododo\": puedes desacoplar 1 material de esta carta; añade a tu mano 1 carta \"Gagaga\", \"Onomat\" o \"Xyz\" de tu Deck." + o("Gagagaga Girl") + " Un Monstruo Xyz \"Utopic Future\" que tenga esta carta como material gana este efecto.\n● Si esta carta es Invocada por Xyz: esta carta puede hacer un segundo ataque durante cada Battle Phase este turno.",
"Buzzsaw Shark": "Puedes seleccionar 1 monstruo de AGUA que controles; Invoca de Modo Especial, desde tu Deck y en Posición de Defensa, 1 monstruo Pez del mismo Nivel que ese monstruo pero con un nombre diferente y, si lo haces, no puede activar sus efectos este turno, y además " + NOEXX + "." + o("Buzzsaw Shark") + " " + W35,
"Lantern Shark": "Si esta carta es Invocada de Modo Normal o Especial: puedes activar este efecto; Invoca de Modo Especial 1 monstruo de AGUA de Nivel 3, 4 o 5 de tu mano en Posición de Defensa, excepto \"Lantern Shark\", y además " + NOEXX + "." + o("Lantern Shark") + " " + W35,
"Abyss Shark": N34 + "Si todos los monstruos que controlas son de AGUA (mín. 1): puedes Invocar esta carta de Modo Especial desde tu mano y, si lo haces, añade a tu mano 1 monstruo Pez de Nivel 3, 4 o 5 de tu Deck, excepto \"Abyss Shark\". Por el resto de este turno, no puedes Invocar monstruos de Modo Especial, excepto monstruos de AGUA, y además duplica el primer daño de batalla infligido a tu adversario este turno por tu monstruo \"Number\" al batallar con otro monstruo." + o("Abyss Shark"),
"Crystal Shark": N34 + "Si esta carta está en tu mano o Cementerio: puedes seleccionar 1 monstruo de AGUA en el Campo; Invoca esta carta de Modo Especial (pero destiérrala cuando deje el Campo) y, si lo haces, reduce a la mitad el ATK de ese monstruo, y además " + NOEXX + "." + o("Crystal Shark"),
"Surfacing Big Jaws": W35 + each2("Surfacing Big Jaws") + " Durante tu Main Phase, si una Carta Mágica fue activada este turno: puedes Invocar esta carta de Modo Especial desde tu mano, y además " + NOEXX + ". Si esta carta es Invocada de Modo Normal o Especial: puedes añadir a tu mano 1 monstruo Pez \"Shark\" de tu Deck.",
"Beautunaful Princess": "Cuando esta carta es Invocada de Modo Normal o Especial: puedes desterrar esta carta; Invoca de Modo Especial 1 monstruo Pez de Nivel 4 o menor de tu Deck, excepto \"Beautunaful Princess\"." + o("Beautunaful Princess"),
"Torpedo Takedown": "Selecciona 1 Monstruo Xyz de AGUA que controles; desacóplale 1 material, inflige 400 de daño a tu adversario por cada carta en tu mano y, si lo haces, ese monstruo gana ATK igual al daño infligido, hasta el final de este turno. Puedes desterrar de tu Cementerio esta carta y 1 Monstruo Xyz de AGUA; roba 2 cartas." + u("Torpedo Takedown"),
"Water Hazard": "Una vez por turno: puedes Invocar de Modo Especial 1 monstruo de AGUA de Nivel 4 o menor de tu mano. No debes controlar monstruos para activar y para resolver este efecto.",
"Moray of Greed": "Baraja en el Deck 2 monstruos de AGUA de tu mano y después roba 3 cartas.",
"Rank-Up-Magic - The Seventh One": "Para activar esta carta, debes robarla en tu robo normal de la Draw Phase, mostrarla y mantenerla mostrada hasta el comienzo de la Main Phase 1. Al comienzo de tu Main Phase 1 de ese mismo turno, puedes: Invocar de Modo Especial, desde tu Deck Extra o Cementerio, 1 monstruo \"Number\" que tenga en su nombre un número entre \"101\" y \"107\", excepto monstruos \"Number C\", y después Invocar de Modo Especial, desde tu Deck Extra, 1 monstruo \"Number C\" con el mismo número en su nombre que el primer monstruo, usándolo como material. (La segunda Invocación Especial se trata como una Invocación Xyz. Transfiere sus materiales al monstruo Invocado.) Sólo puedes aplicar este efecto de \"Rank-Up-Magic - The Seventh One\" una vez por Duelo.",
"Toadally Awesome": "2 monstruos Aqua de Nivel 2\nUna vez por turno, durante la Standby Phase: puedes desacoplar 1 material de esta carta; Invoca de Modo Especial 1 monstruo \"Frog\" de tu Deck. Una vez por turno, cuando tu adversario activa una Carta Mágica/de Trampa o un efecto de monstruo (Efecto Rápido): puedes mandar al Cementerio 1 monstruo Aqua de tu mano o boca arriba de tu Campo; niega la activación y, si lo haces, destruye esa carta, y después puedes Colocarla en tu Campo. Si esta carta es mandada al Cementerio: puedes seleccionar 1 monstruo de AGUA en tu Cementerio; añádelo a tu mano.",
"N.As.H. Knight": "2 monstruos de Nivel 5\nNo puede ser destruido en batalla mientras haya un monstruo \"Number\" en el Campo. Durante la Main Phase (Efecto Rápido): puedes desacoplar 2 materiales de esta carta; acopla a esta carta como material 1 Monstruo Xyz \"Number\" de tu Deck Extra que tenga en su nombre un número entre \"101\" y \"107\", y después puedes acoplar a esta carta como material otro monstruo boca arriba en el Campo." + o("N.As.H. Knight"),
"CXyz N.As.Ch. Knight": "3 monstruos de Nivel 6\nTambién puedes Invocar esta carta por Xyz usando un \"N.As.H. Knight\" que controles. " + TR + "No puede ser destruido por efectos de cartas. Puedes desacoplar 1 material de esta carta; Invoca de Modo Especial, desde tu Deck Extra, 1 Monstruo Xyz \"Number\" que tenga en su nombre un número entre \"101\" y \"107\", usando como material esta carta boca arriba que controlas, pero destrúyelo durante la próxima End Phase de tu adversario. (Esto se trata como una Invocación Xyz. Transfiere sus materiales al monstruo Invocado.)" + o("CXyz N.As.Ch. Knight"),
"Number 4: Stealth Kragen": "2 monstruos de AGUA de Nivel 4\nTodos los monstruos boca arriba en el Campo se convierten en AGUA. Una vez por turno, durante la Main Phase (Efecto Rápido): puedes destruir 1 monstruo de AGUA que controle tu adversario y, si lo haces, inflígele daño igual a la mitad del ATK que tenía en el Campo. Si esta carta Invocada por Xyz es destruida: puedes Invocar de Modo Especial uno o más \"Stealth Kragen Spawn\" de tu Deck Extra, hasta el número de materiales que tenía esta carta, y después puedes acoplar hasta 1 monstruo de AGUA de tu Cementerio a cada uno de esos monstruos Invocados de Modo Especial como material.",
"Valiant Shark Lancer": "2 monstruos de Nivel 5\nPuedes seleccionar 1 monstruo que controle tu adversario; desacopla 1 material de un monstruo que controles y, si lo haces, destruye ese monstruo. Éste es un Efecto Rápido si controlas otro Monstruo Xyz de AGUA. Si uno o más Monstruos Xyz de AGUA distintos que controlas son destruidos en batalla o por un efecto de carta mientras controlas este monstruo: puedes tomar 1 Mágica de tu Deck y ponerla en la parte superior de tu Deck." + e("Valiant Shark Lancer"),
"Galaxy-Eyes Afterglow Dragon": "Si controlas un monstruo \"Galaxy-Eyes\": puedes Invocar esta carta de Modo Especial desde tu mano en Posición de Defensa. Si esta carta es desacoplada de un Monstruo Xyz para activar el efecto de ese monstruo: puedes tomar 1 " + GEPD + " de tu mano o Deck e Invocarlo de Modo Especial o acoplarlo como material a un Monstruo Xyz que controles, y después, si activaste este efecto durante la Battle Phase, duplica el ATK de todos los Monstruos Xyz \"Number\" que controles." + e("Galaxy-Eyes Afterglow Dragon"),
"Photon Orbital": "Durante tu Main Phase: puedes seleccionar 1 monstruo " + PG + " que controles; equípale este monstruo desde tu mano o Campo. Gana 500 ATK, y además no puede ser destruido en batalla. Puedes mandar esta Carta de Equipo al Cementerio; añade a tu mano 1 monstruo " + PG + " de tu Deck, excepto \"Photon Orbital\"." + o("Photon Orbital"),
"Photon Vanisher": "No puede ser Invocado de Modo Normal ni Colocado. Debe ser primero Invocado de Modo Especial (desde tu mano) mientras controlas un monstruo " + PG + ". No puede atacar el turno en que es Invocado de Modo Especial. Sólo puedes Invocar de Modo Especial \"Photon Vanisher\" una vez por turno. Si esta carta es Invocada de Modo Especial: puedes añadir a tu mano 1 " + GEPD + " de tu Deck. Un Monstruo Xyz que fue Invocado usando como material esta carta en el Campo gana este efecto.\n● Destierra cualquier monstruo destruido en batalla con esta carta.",
"Photon Advancer": "Si hay un monstruo \"Photon\" en el Campo, puedes Invocar esta carta de Modo Especial (desde tu mano). Sólo puedes Invocar de Modo Especial \"Photon Advancer\" una vez por turno de esta forma. Gana 1000 ATK si hay otro monstruo \"Photon\" en el Campo.",
"Galaxy Summoner": "Si esta carta es Invocada de Modo Normal o Especial: puedes seleccionar 1 monstruo " + PG + " en tu Cementerio, excepto \"Galaxy Summoner\"; Invócalo de Modo Especial en Posición de Defensa. Puedes seleccionar otro monstruo de LUZ que controles; se convierte en Nivel 4 hasta el final de este turno." + e("Galaxy Summoner"),
"Photon Emperor": "Si esta carta es mandada al Cementerio, excepto desde el Campo, mientras otro monstruo " + PG + " está en tu Campo o en tu Cementerio: puedes Invocar esta carta de Modo Especial en Posición de Defensa." + o("Photon Emperor") + " Después de Invocar esta carta de Modo Normal o Especial, puedes Invocar de Modo Normal 1 monstruo de LUZ durante tu Main Phase este turno, además de tu Invocación Normal/Colocación. (Sólo puedes ganar este efecto una vez por turno.)",
"Galaxy Brave": "Si esta carta está en tu mano: puedes mostrar 1 monstruo \"Photon\" en tu mano; Invoca esta carta de Modo Especial y, si lo haces, su Nivel se convierte en el Nivel de ese monstruo \"Photon\". Si esta carta es Invocada de Modo Normal o Especial: puedes seleccionar 1 monstruo \"Galaxy\" en tu Cementerio; el ATK/DEF de esta carta se convierten en el ATK/DEF de ese monstruo." + e("Galaxy Brave"),
"Galaxy Trance": "Paga 2000 LP y después selecciona 1 monstruo \"Photon\" en tu Cementerio; Invoca de Modo Especial ese monstruo y 1 monstruo \"Galaxy\" del mismo Nivel de tu Deck, ambos en Posición de Defensa y, si lo haces, el ATK de cada monstruo se convierte en 2000, y además sus efectos son negados." + a("Galaxy Trance") + " No puedes Invocar monstruos de Modo Normal o Especial durante el turno en que actives esta carta, excepto monstruos \"Photon\" y \"Galaxy\".",
"Photon Hand": "Si controlas un monstruo " + PG + ": paga 1000 LP y después selecciona 1 monstruo que controle tu adversario; toma su control. Si no controlas " + GEPD + " al activarla, sólo puedes seleccionar un Monstruo Xyz." + a("Photon Hand"),
"Photon Change": "Manda esta carta al Cementerio durante tu 2ª Standby Phase después de su activación. Sólo puedes usar el siguiente efecto de \"Photon Change\" una vez por turno. Manda al Cementerio 1 monstruo " + PG + " que controles para activar 1 de estos efectos o, si mandas " + GEPD + ", puedes activar ambos, en secuencia;\n● Invoca de Modo Especial 1 monstruo \"Photon\" de tu Deck con un nombre original diferente al del monstruo mandado.\n● Añade a tu mano 1 carta \"Photon\" de tu Deck, excepto \"Photon Change\".",
"Galaxy-Eyes Full Armor Photon Dragon": "3 monstruos de Nivel 8\nTambién puedes Invocar esta carta por Xyz usando como material un Monstruo Xyz \"Galaxy-Eyes\" que controles, excepto \"Galaxy-Eyes Full Armor Photon Dragon\". " + TR + "Una vez por turno: puedes seleccionar hasta 2 Cartas de Equipo equipadas a esta carta; acóplalas a esta carta como material. Una vez por turno: puedes desacoplar 1 material de esta carta y después seleccionar 1 carta boca arriba que controle tu adversario; destrúyela.",
"Number 90: Galaxy-Eyes Photon Lord": L8 + "Si esta carta tiene una carta \"Photon\" como material, no puede ser destruida por efectos de cartas." + each2("Number 90: Galaxy-Eyes Photon Lord") + "\n● Cuando un monstruo del adversario activa su efecto (Efecto Rápido): puedes desacoplar 1 material de esta carta; niega el efecto de ese monstruo y, si el material desacoplado era una carta \"Galaxy\", destruye esa carta.\n● Durante el turno de tu adversario (Efecto Rápido): puedes tomar 1 carta " + PG + " de tu Deck y añadirla a tu mano o acoplarla a esta carta como material.",
"Galaxy-Eyes Cipher Dragon": L8 + "Una vez por turno: puedes desacoplar 1 material de esta carta y después seleccionar 1 monstruo boca arriba que controle tu adversario; los monstruos que controles no pueden atacar directamente a tu adversario por el resto de este turno, excepto esta carta, y además toma el control del monstruo seleccionado hasta la End Phase, pero mientras este efecto esté aplicado, sus efectos son negados, su ATK se convierte en 3000, y además su nombre se convierte en \"Galaxy-Eyes Cipher Dragon\".",
"Galaxy-Eyes Cipher Blade Dragon": "3 monstruos de Nivel 9\nTambién puedes Invocar esta carta por Xyz usando como material un Monstruo Xyz \"Galaxy-Eyes\" de Rango 8 que controles. " + TR + "No puede ser usado como material para una Invocación Xyz. Una vez por turno: puedes desacoplar 1 material de esta carta y después seleccionar 1 carta en el Campo; destrúyela. Si esta carta Invocada por Xyz que controlas es destruida en batalla con un monstruo atacante del adversario, o destruida por un efecto de carta del adversario, y mandada a tu Cementerio: puedes seleccionar 1 \"Galaxy-Eyes Cipher Dragon\" en tu Cementerio; Invócalo de Modo Especial.",
"Galaxy-Eyes Cipher X Dragon": "2 monstruos de Nivel 10\nUna vez por turno, también puedes Invocar por Xyz \"Galaxy-Eyes Cipher X Dragon\" usando como material un monstruo \"Cipher Dragon\" que controles. " + TR + "Puedes desacoplar 2 materiales de esta carta; tu adversario no puede seleccionar con efectos de cartas a los monstruos de LUZ que controles, hasta el final del turno de tu adversario. Una vez por turno, durante tu Standby Phase: puedes devolver al Deck Extra 1 Monstruo Xyz Dragón de Rango 9 o menor de tu Cementerio y después puedes Invocar de Modo Especial ese monstruo desde tu Deck Extra, usando como material esta carta que controlas. (Esto se trata como una Invocación Xyz. Transfiere los materiales de esta carta al monstruo Invocado.)",
"Number 95: Galaxy-Eyes Dark Matter Dragon": "3 monstruos de Nivel 9\nTambién puedes Invocar esta carta por Xyz usando como Material Xyz un Monstruo Xyz \"Galaxy-Eyes\" que controles. (Los Materiales Xyz acoplados a ese monstruo también se convierten en Materiales Xyz de esta carta.) No puede ser usado como Material Xyz para una Invocación Xyz. Cuando esta carta es Invocada por Xyz: puedes mandar al Cementerio 3 monstruos Dragón con nombres diferentes de tu Deck; tu adversario destierra 3 monstruos de su Deck. Puedes desacoplar 1 Material Xyz de esta carta; esta carta puede hacer hasta 2 ataques a monstruos durante cada Battle Phase este turno.",
"Galaxy Photon Dragon": L4 + "Los otros monstruos de LUZ que controles ganan 500 ATK." + each2("Galaxy Photon Dragon") + " Puedes desacoplar 1 material de esta carta; toma 1 carta " + PG + " de tu Deck y añádela a tu mano o mándala al Cementerio. Si uno o más monstruos de LUZ son Invocados de Modo Especial a tu Campo (excepto durante el Damage Step): puedes seleccionar 1 de esos monstruos; su Nivel se convierte en 4 u 8 hasta el final de este turno.",
"Starliege Photon Blast Dragon": L4 + "Si esta carta es Invocada por Xyz: puedes Invocar de Modo Especial 1 monstruo \"Photon\" de tu mano. Mientras este monstruo Invocado por Xyz esté en el Campo, tu adversario no puede seleccionar con efectos de cartas a los monstruos que controles con 2000 o más ATK, y además no pueden ser destruidos por efectos de cartas del adversario. Una vez por turno del adversario (Efecto Rápido): puedes desacoplar 1 material de esta carta y después seleccionar 1 de tus " + GEPD + " que esté desterrado o en tu Cementerio; Invócalo de Modo Especial.",
"Numeron Wall": "Si no controlas cartas, excepto \"Numeron Wall\" (Efecto Rápido): puedes mandar esta carta al Cementerio desde tu mano o Campo; activa 1 " + NN + " directamente desde tu mano o Deck." + o("Numeron Wall") + " Cuando recibes daño de batalla: puedes Invocar esta carta de Modo Especial desde tu mano y, si lo haces, termina la Battle Phase después del Damage Step.",
"Numeron Network": "Durante tu Main Phase, puedes: mandar al Cementerio 1 Carta Mágica Normal \"Numeron\" de tu Deck que cumpla sus condiciones de activación; este efecto se convierte en el efecto de esa Mágica cuando esa carta es activada." + o("Numeron Network") + " Los Monstruos Xyz \"Numeron\" que controles pueden activar efectos sin desacoplar materiales.",
"Numeron Calling": "Si " + NN + " está en tu Zona de Campo y no controlas monstruos: Invoca de Modo Especial hasta 4 Monstruos Xyz \"Numeron Gate\" con nombres diferentes de tu Deck Extra, pero destiérralos durante la End Phase, y además sólo puedes Invocar de Modo Normal o Especial una vez por el resto de este turno.",
"Number 1: Numeron Gate Ekam": GATE,
"Number 2: Numeron Gate Dve": GATE,
"Number 3: Numeron Gate Trini": GATE,
"Number 4: Numeron Gate Catvari": GATE,
"Number C1: Numeron Chaos Gate Sunya": "4 monstruos de Nivel 2\nTambién puedes Invocar esta carta por Xyz usando como material un \"Number 1: Numeron Gate Ekam\" que controles. " + TR + "Si esta carta es Invocada por Xyz: destierra todos los monstruos en el Campo. Una vez por turno, durante tu próxima Standby Phase después de que esta carta fue desterrada: puedes Invocar de Modo Especial esta carta desterrada y después, si " + NN + " está en tu Zona de Campo, inflige a tu adversario daño igual al ATK combinado de todos los Monstruos Xyz desterrados.",
"Number C1000: Numerounius": "5 monstruos de Nivel 12\nUna vez por turno (Efecto Rápido): puedes desacoplar 1 material de esta carta; destruye otro monstruo en el Campo. Al final de la Battle Phase: destruye tantos otros monstruos en el Campo como sea posible (mín. 1) y después puedes Invocar de Modo Especial a tu Campo 1 monstruo del Cementerio de tu adversario en Posición de Defensa. Si esta carta que controlas es destruida por un efecto de carta del adversario mientras tiene material, y es mandada a tu Cementerio: puedes Invocar de Modo Especial 1 \"Number iC1000: Numerounius Numerounia\" de tu Deck Extra y, si lo haces, acóplale esta carta como material.",
"Number iC1000: Numerounius Numerounia": "5 monstruos de Nivel 13\nSi esta carta es Invocada de Modo Especial por el efecto de \"Number C1000: Numerounius\", gana 100.000 ATK/DEF sólo durante el turno de tu adversario, y además aplica los siguientes efectos desde el comienzo del próximo turno después de que esta carta fue Invocada de Modo Especial.\n● Los monstruos que controle tu adversario deben atacar a esta carta, si pueden.\n● Al final del turno de tu adversario, si esta carta no batalló, ganas el Duelo.\nCuando un monstruo del adversario declara un ataque: puedes desacoplar 1 material de esta carta; niega el ataque y, si lo haces, gana LP igual al ATK de ese monstruo.",
}
